$ErrorActionPreference='Stop'
$root='C:\Users\JAMAL\Desktop\Flafy'
$dist=Join-Path $root 'dist'
$utf8=New-Object System.Text.UTF8Encoding($false)
New-Item -ItemType Directory -Force -Path $dist|Out-Null
$html=@'
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flafy</title><link rel="stylesheet" href="styles.css"></head><body><div class="app"><header class="top"><div class="identity"><div class="avatar">F</div><div><h1>Flafy</h1><p>Personal Control Room · Jamal & Sol</p></div></div><div class="topchips"><span class="chip live">● SYSTEM LIVE</span><span class="chip" id="topClock">--:--</span></div></header><main class="dashboard"><section class="hero panel"><div class="heroTop"><div><span class="kicker">FLAFY // CONTROL ROOM</span><h2 id="greeting">مساء الخير، جمال</h2><p>كل شغلك وحالة الجهاز والأشياء المهمة قدامك بمكان واحد.</p></div><div class="weatherMini"><div id="weatherIcon">◐</div><div><b id="weatherTemp">--°</b><span id="weatherText">Hameln</span></div></div></div><div class="focusBox"><div class="sectionLabel">FOCUS NOW</div><input id="focusInput" maxlength="120" value="ركّز على شغلة رئيسية واحدة، والباقي Flafy تراقبه."/><div class="focusMeta"><span>اضغط Enter للحفظ</span><span id="focusSaved">محفوظ محليًا</span></div></div><div class="heroBottom"><div><div class="bigClock" id="clock">--:--</div><div class="date" id="date">---</div></div><div class="heroStats"><div><span>MODE</span><b>Borderless Fullscreen</b></div><div><span>CORE</span><b>Tauri + Rust</b></div><div><span>STATE</span><b id="heroState">Ready</b></div></div></div></section><section class="projects panel"><div class="head"><div><b>Projects</b><span>Workspace</span></div><button class="ghost" id="refreshProjects">↻</button></div><div class="projectList"><button data-open="flafy"><span class="dot good"></span><div><b>Flafy</b><small>Main control room</small></div><em>ACTIVE</em></button><button data-open="mofakrati"><span class="dot" id="mofDot"></span><div><b>مفكرتي</b><small>Notebook desktop app</small></div><em id="mofState">CHECK</em></button><button><span class="dot amber"></span><div><b>MedFlux</b><small>Canonical project</small></div><em>MONITOR</em></button><button><span class="dot good"></span><div><b>Net Download Manager</b><small>Download utility</small></div><em>READY</em></button><button><span class="dot"></span><div><b>Project Zomboid</b><small>Mods & tools</small></div><em>IDLE</em></button></div></section><section class="system panel"><div class="head"><div><b>System Health</b><span>Live telemetry</span></div><span class="tiny" id="telemetryState">LIVE</span></div><div class="metrics"><div class="metric"><div><span>CPU</span><b id="cpuVal">--%</b></div><div class="bar"><i id="cpuBar"></i></div></div><div class="metric"><div><span>Memory</span><b id="ramVal">--%</b></div><div class="bar"><i id="ramBar"></i></div></div><div class="metric"><div><span>Storage</span><b id="diskVal">--%</b></div><div class="bar"><i id="diskBar"></i></div></div></div><div class="ramLine" id="ramText">قراءة الجهاز…</div></section><section class="actions panel"><div class="head"><div><b>Quick Actions</b><span>Launch</span></div></div><div class="actionGrid"><button data-open="desktop">Desktop<span>↗</span></button><button data-open="downloads">Downloads<span>↗</span></button><button data-open="flafy">Flafy Folder<span>↗</span></button><button id="refreshAll">Refresh All<span>↻</span></button></div></section><section class="today panel"><div class="head"><div><b>Today</b><span>What matters</span></div></div><div class="todayGrid"><article><span>WEATHER</span><b id="todayWeather">Loading…</b><small>Hameln</small></article><article><span>FOCUS</span><b id="todayFocus">شغلة واحدة رئيسية</b><small>Stored locally</small></article><article><span>PROJECTS</span><b id="todayProjects">Checking…</b><small>Workspace state</small></article><article><span>SYSTEM</span><b id="todaySystem">Reading…</b><small>Live device health</small></article></div></section><section class="activity panel"><div class="head"><div><b>Recent Activity</b><span>Local session</span></div><button class="ghost" id="clearActivity">Clear</button></div><div class="activityList" id="activityList"></div></section><section class="sol panel"><div class="head"><div><b>Flafy Intelligence</b><span>Signal, not noise</span></div></div><div class="solGrid"><article><span>NOW</span><b id="solNow">الواجهة جاهزة وتقرأ حالة الجهاز.</b><small>ما في بيانات نظام وهمية.</small></article><article><span>PROJECTS</span><b>خلي مشروع واحد أساسي والباقي للمراقبة.</b><small>الوصول للمجلدات صار مباشر من اللوحة.</small></article><article><span>PERFORMANCE</span><b>Flafy خفيفة ومبنية على Tauri + Rust.</b><small>التحديثات محدودة وما في مؤثرات مستمرة.</small></article></div></section></main><footer><span>Flafy 1.0 · Personal Control Room</span><span id="footerStatus">Initializing…</span></footer></div><script src="app.js"></script></body></html>
'@
$css=@'
:root{--bg:#080b10;--panel:#111722;--panel2:#0d131c;--line:#263145;--text:#f5f7fb;--muted:#8793a8;--blue:#6fa8ff;--violet:#9d8cff;--green:#62d7a1;--amber:#d7ad69}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:radial-gradient(circle at 15% 0,#14233a 0,transparent 28%),radial-gradient(circle at 85% 0,#21172f 0,transparent 25%),var(--bg);color:var(--text);font-family:Segoe UI,Tahoma,Arial,sans-serif}.app{height:100vh;padding:18px 22px;display:grid;grid-template-rows:auto 1fr auto;gap:14px}.top{display:flex;align-items:center;justify-content:space-between}.identity{display:flex;align-items:center;gap:12px}.avatar{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(145deg,#dbe8ff,#9ebeff,#b7a9ff);color:#0d1118;font-weight:900;font-size:18px}.identity h1{margin:0;font-size:22px}.identity p{margin:3px 0 0;color:var(--muted);font-size:10px}.topchips{display:flex;gap:8px}.chip{border:1px solid var(--line);background:#ffffff04;border-radius:10px;padding:8px 11px;font-size:10px;color:var(--muted)}.chip.live{color:var(--green)}.dashboard{min-height:0;display:grid;grid-template-columns:1fr 1.35fr 1fr;grid-template-rows:1.1fr .8fr .95fr;gap:12px}.panel{background:linear-gradient(180deg,#131925f2,#0e141ef2);border:1px solid var(--line);border-radius:18px;box-shadow:0 18px 50px #0005;overflow:hidden}.hero{grid-column:2;grid-row:1/3;padding:26px;display:flex;flex-direction:column;justify-content:space-between}.heroTop{display:flex;justify-content:space-between;gap:20px}.kicker{font-size:9px;color:var(--blue)}.hero h2{font-size:36px;margin:8px 0}.hero p{color:var(--muted);font-size:12px}.weatherMini{display:flex;align-items:center;gap:10px;direction:ltr}.weatherMini>div:first-child{font-size:28px}.weatherMini b{font-size:25px}.weatherMini span{display:block;color:var(--muted);font-size:9px}.focusBox{padding:17px;border:1px solid #2e3c54;border-radius:15px;background:#0c121b}.sectionLabel{font-size:9px;color:var(--blue);margin-bottom:8px}.focusBox input{width:100%;border:0;outline:0;background:transparent;color:var(--text);font-size:18px;font-weight:700;text-align:right}.focusMeta{display:flex;justify-content:space-between;margin-top:10px;color:var(--muted);font-size:9px}.heroBottom{display:flex;align-items:end;justify-content:space-between;gap:20px}.bigClock{font-size:58px;font-weight:700;letter-spacing:-2px}.date{font-size:10px;color:var(--muted);margin-top:4px}.heroStats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;min-width:360px}.heroStats div{border:1px solid #263145;border-radius:10px;padding:10px;background:#ffffff03}.heroStats span{display:block;color:var(--muted);font-size:8px}.heroStats b{display:block;font-size:9px;margin-top:5px}.head{height:46px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.head>div b{display:block;font-size:12px}.head>div span{display:block;font-size:8px;color:var(--muted);margin-top:2px}.ghost{border:1px solid var(--line);background:#ffffff04;color:var(--muted);border-radius:8px;padding:5px 8px;cursor:pointer}.projects{grid-column:1;grid-row:1}.projectList{padding:10px;display:grid;gap:7px}.projectList button{min-height:47px;border:1px solid #273146;background:#ffffff03;color:var(--text);border-radius:11px;padding:8px 10px;display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;text-align:right;cursor:pointer}.projectList button:hover,.actionGrid button:hover{background:#ffffff08}.projectList b{font-size:10px}.projectList small{display:block;color:var(--muted);font-size:8px;margin-top:2px}.projectList em{font-style:normal;font-size:8px;color:var(--muted)}.dot{width:7px;height:7px;border-radius:50%;background:#718097}.dot.good{background:var(--green)}.dot.amber{background:var(--amber)}.system{grid-column:3;grid-row:1}.tiny{font-size:8px;color:var(--green)}.metrics{padding:15px}.metric{margin-bottom:16px}.metric>div:first-child{display:flex;justify-content:space-between;color:var(--muted);font-size:9px;margin-bottom:6px}.bar{height:7px;background:#202a39;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--blue),var(--violet));border-radius:99px;transition:width .35s}.ramLine{padding:0 15px;color:var(--muted);font-size:9px}.actions{grid-column:1;grid-row:2}.actionGrid{padding:10px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.actionGrid button{height:52px;border:1px solid #273146;background:#ffffff03;color:var(--text);border-radius:11px;padding:0 12px;display:flex;align-items:center;justify-content:space-between;cursor:pointer}.today{grid-column:3;grid-row:2}.todayGrid{padding:10px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.todayGrid article{padding:11px;border:1px solid #273146;background:#ffffff03;border-radius:11px;min-height:78px}.todayGrid span{font-size:8px;color:var(--blue)}.todayGrid b{display:block;font-size:10px;margin:7px 0}.todayGrid small{color:var(--muted);font-size:8px}.activity{grid-column:1;grid-row:3}.activityList{padding:10px;display:grid;gap:7px;max-height:calc(100% - 46px);overflow:auto}.activityItem{display:flex;justify-content:space-between;gap:10px;padding:9px 10px;border:1px solid #263145;border-radius:10px;background:#ffffff03;font-size:9px}.activityItem span:last-child{color:var(--muted)}.sol{grid-column:2/4;grid-row:3}.solGrid{height:calc(100% - 46px);padding:10px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.solGrid article{padding:14px;border:1px solid #273146;background:#ffffff03;border-radius:11px}.solGrid span{font-size:8px;color:var(--blue)}.solGrid b{display:block;font-size:11px;margin:8px 0}.solGrid small{font-size:9px;color:var(--muted);line-height:1.6}footer{display:flex;justify-content:space-between;color:var(--muted);font-size:8px}@media(max-width:1250px){.heroStats{min-width:280px}.hero h2{font-size:30px}.bigClock{font-size:48px}}
'@
$js=@'
const E=id=>document.getElementById(id);const invoke=(cmd,args={})=>window.__TAURI__?.core?.invoke(cmd,args);let activity=JSON.parse(localStorage.getItem('flafyActivity')||'[]');function logActivity(text){activity.unshift({text,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});activity=activity.slice(0,8);localStorage.setItem('flafyActivity',JSON.stringify(activity));renderActivity()}function renderActivity(){E('activityList').innerHTML=activity.length?activity.map(a=>`<div class="activityItem"><span>${a.text}</span><span>${a.time}</span></div>`).join(''):'<div class="activityItem"><span>ما في نشاط بعد.</span><span>—</span></div>'}function tick(){const d=new Date();const t=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});E('clock').textContent=t;E('topClock').textContent=t;E('date').textContent=d.toLocaleDateString('ar-DE',{weekday:'long',year:'numeric',month:'long',day:'numeric'});E('greeting').textContent=(d.getHours()<12?'صباح الخير، جمال':'مساء الخير، جمال')}async function stats(){try{const s=await invoke('system_stats');for(const [k,v] of [['cpu',s.cpu],['ram',s.ram],['disk',s.storage]]){E(k+'Val').textContent=Math.round(v)+'%';E(k+'Bar').style.width=Math.min(100,v)+'%'}E('ramText').textContent=`RAM ${s.used_ram_gb.toFixed(1)} / ${s.total_ram_gb.toFixed(1)} GB`;E('todaySystem').textContent=`CPU ${Math.round(s.cpu)}% · RAM ${Math.round(s.ram)}%`;E('footerStatus').textContent='Telemetry online';E('telemetryState').textContent='LIVE'}catch(e){E('footerStatus').textContent='Telemetry unavailable';E('telemetryState').textContent='OFFLINE'}}async function projects(){try{const p=await invoke('project_status');E('mofState').textContent=p.mofakrati?'READY':'NOT FOUND';E('mofDot').className='dot '+(p.mofakrati?'good':'');const n=[p.flafy,p.mofakrati,p.downloads].filter(Boolean).length;E('todayProjects').textContent=n+'/3 local targets ready'}catch(e){E('todayProjects').textContent='Unavailable'}}async function weather(){try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=52.10&longitude=9.36&current=temperature_2m,weather_code&timezone=Europe%2FBerlin');const j=await r.json();const temp=Math.round(j.current.temperature_2m);const c=j.current.weather_code;const text=c===0?'صافي':c<4?'غائم جزئيًا':c<50?'غائم':c<70?'مطر':'طقس متغير';E('weatherTemp').textContent=temp+'°';E('weatherText').textContent='Hameln · '+text;E('todayWeather').textContent=temp+'° · '+text;E('weatherIcon').textContent=c===0?'○':c<4?'◐':'●'}catch(e){E('weatherText').textContent='Hameln · unavailable';E('todayWeather').textContent='Unavailable'}}document.querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{const k=b.dataset.open;try{await invoke('open_location',{kind:k});logActivity('فتح '+b.textContent.trim())}catch(e){logActivity('تعذر فتح '+k)}});E('refreshProjects').onclick=()=>{projects();logActivity('تحديث حالة المشاريع')};E('refreshAll').onclick=()=>{stats();projects();weather();logActivity('تحديث كامل للوحة')};E('clearActivity').onclick=()=>{activity=[];localStorage.removeItem('flafyActivity');renderActivity()};const fi=E('focusInput');const saved=localStorage.getItem('flafyFocus');if(saved)fi.value=saved;E('todayFocus').textContent=fi.value;fi.addEventListener('keydown',e=>{if(e.key==='Enter'){localStorage.setItem('flafyFocus',fi.value);E('todayFocus').textContent=fi.value;E('focusSaved').textContent='تم الحفظ الآن';logActivity('تحديث Focus')}});tick();renderActivity();stats();projects();weather();setInterval(tick,1000);setInterval(stats,4000);setInterval(projects,30000);setInterval(weather,900000);logActivity('تشغيل Flafy Control Room');
'@
[IO.File]::WriteAllText((Join-Path $dist 'index.html'),$html,$utf8)
[IO.File]::WriteAllText((Join-Path $dist 'styles.css'),$css,$utf8)
[IO.File]::WriteAllText((Join-Path $dist 'app.js'),$js,$utf8)
Get-Process flafy -ErrorAction SilentlyContinue|Stop-Process -Force
Start-Sleep 2
Set-Location $root
npm run tauri build
if($LASTEXITCODE -ne 0){'BUILD_FAILED'|Set-Content (Join-Path $root 'FLAFY_UI_FAILED.txt');exit 1}
$exe=Join-Path $root 'src-tauri\target\release\flafy.exe'
Start-Process $exe
'UI_COMPLETE`r`nBUILD_OK`r`nSTARTED_OK'|Set-Content (Join-Path $root 'FLAFY_UI_COMPLETE.txt')
Write-Output 'FLAFY FULL CONTROL ROOM BUILT AND STARTED'
